function imgGain(name) {
  const out = [];
  for (const m of ["xray", "ct"]) {
    const r = (R.imaging || {})[m]; if (!r) continue;
    const a = r.models[name], b = r.models["Paper CNN"];
    if (a && b) out.push(`${m === "xray" ? "X-ray" : "CT"} ${a.accuracy - b.accuracy >= 0 ? "+" : ""}${fx(a.accuracy - b.accuracy)} pt acc, AUC ${fx(a.auc, 4)}`);
  }
  return out.join(" · ") || "see results";
}
function blGap() {
  const b = R.blood; if (!b) return "";
  return `ERT acc ${fx(b.paper_protocol.ERT.accuracy)} → ${fx(b.honest_smoteenn.ERT.accuracy)} when patients are kept apart`;
}
const aucArrow = (A, B) => (A && B ? `AUC ${fx(A.auc, 3)} → ${fx(B.auc, 3)}` : "");
const blAbl = () => R.blood && aucArrow((R.blood.ablation || [])[0], (R.blood.ablation || [])[2]);
const blTune = () => R.blood && aucArrow((R.blood.ablation || [])[2], (R.blood.improved || {})["Tuned ERT"]);
const blStack = () => R.blood && aucArrow((R.blood.improved || {})["Tuned ERT"], (R.blood.improved || {})["Stacked ensemble"]);

